Object.assign(SNIP,{"h15khuon": "long long lo = 0, hi = 2000000000000000000LL;   // ok(lo) sai, ok(hi) đúng\nwhile (hi - lo > 1) {\n    long long mid = lo + (hi - lo) / 2;\n    if (ok(mid)) hi = mid;\n    else lo = mid;\n}\n// hi là giá trị nhỏ nhất làm ok đúng"});PRESET_NOTES["l15"]={"Ví dụ: Cắt gỗ, độ cao cưa lớn nhất": "Cưa ở độ cao 15 lấy được 5 + 2 = 7 mét: đủ. Cưa ở 16 chỉ được 4 + 1 = 5 mét. Đáp án 15. Bài tìm giá trị lớn nhất nên lo là phía đạt.", "Ví dụ: Máy sản xuất, thời gian ít nhất": "Trong 8 giây, ba máy làm được 2 + 4 + 1 = 7 sản phẩm: đủ. Trong 7 giây chỉ được 2 + 3 + 1 = 6. Đáp án 8. Dừng sớm khi s ≥ P để s không tràn."};EX_HINTS["l15"]=[["Cưa càng thấp càng nhiều gỗ: điều kiện “đủ gỗ” đơn điệu.", "Tìm H lớn nhất còn đủ: lo đạt (0 luôn đạt vì đề bảo đảm có đáp án), hi = max + 1 không đạt.", "Tổng gỗ có thể tới 10¹⁴: long long."], ["Trong T giây, máy i làm được T / tᵢ sản phẩm.", "hi = min(t) · P luôn đủ; có thể tới 10¹⁸.", "Dừng cộng ngay khi tổng ≥ P để không tràn."], ["Kiểm tra M: đi từ trái, nhét số vào đoạn hiện tại tới khi vượt M thì mở đoạn mới; đếm số đoạn.", "Chia được thành ≤ k đoạn thì cũng chia được đúng k đoạn (tách bớt đoạn).", "M phải ≥ max(a): đặt lo = max − 1."]];
/* ===================== BÀI 15 · Tìm kiếm nhị phân trên kết quả ===================== */
/* Bài 15 · Tìm kiếm nhị phân trên kết quả
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
hsgLesson(document.getElementById("gate-l15"),"quiz15");
const PR15=[{label:"Ví dụ: Cắt gỗ, độ cao cưa lớn nhất",input:"4 7\n20 15 10 17",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"CATGO.INP\", \"r\")) {\n        freopen(\"CATGO.INP\", \"r\", stdin);\n        freopen(\"CATGO.OUT\", \"w\", stdout);\n    }\n    int n;\n    long long M;\n    cin >> n >> M;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    // lo: cưa ở độ cao lo vẫn đủ gỗ; hi: cưa ở độ cao hi thì không đủ\n    long long lo = 0, hi = *max_element(a.begin(), a.end()) + 1;\n    while (hi - lo > 1) {\n        long long mid = lo + (hi - lo) / 2;\n        long long go = 0;\n        for (long long x : a)\n            if (x > mid) go += x - mid;\n        if (go >= M) lo = mid;\n        else hi = mid;\n    }\n    cout << lo << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"},{type:"vars",names:["lo","mid","hi","go"]}]},{label:"Ví dụ: Máy sản xuất, thời gian ít nhất",input:"3 7\n3 2 5",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"MAYSX.INP\", \"r\")) {\n        freopen(\"MAYSX.INP\", \"r\", stdin);\n        freopen(\"MAYSX.OUT\", \"w\", stdout);\n    }\n    int n;\n    long long P;\n    cin >> n >> P;\n    vector<long long> t(n);\n    for (auto& x : t) cin >> x;\n    long long lo = 0, hi = *min_element(t.begin(), t.end()) * P;   // ok(hi) chắc chắn đúng\n    while (hi - lo > 1) {\n        long long mid = lo + (hi - lo) / 2;\n        long long s = 0;\n        bool du = false;\n        for (long long x : t) {\n            s += mid / x;\n            if (s >= P) {\n                du = true;\n                break;\n            }\n        }\n        if (du) hi = mid;\n        else lo = mid;\n    }\n    cout << hi << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["lo","mid","hi","s"]}]}];
const sim15=makeSim2(document.getElementById("sim-l15"),{id:"s15",presets:PR15,tools:true});
makeEx2(document.getElementById("ex-l15"),sim15,[{t:"Cắt gỗ",d:"File CATGO.INP: dòng 1 là n, M (1 ≤ n ≤ 10^5, 1 ≤ M ≤ 2·10^9); dòng 2 là chiều cao n cây (1 ≤ aᵢ ≤ 10^9). Đặt lưỡi cưa ở độ cao H (số nguyên ≥ 0), mỗi cây cao hơn H bị cắt phần trên H. Ghi vào CATGO.OUT độ cao H lớn nhất mà tổng gỗ thu được vẫn ≥ M. Dữ liệu bảo đảm có đáp án.",tests:[{in:"4 7\n20 15 10 17",out:"15"},{in:"5 20\n4 42 40 26 46",out:"36"},{in:"1 1\n1",out:"0"},{in:"3 3000000000\n1000000000 1000000000 1000000000",out:"0"},{in:"2 1\n1000000000 1",out:"999999999"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"CATGO.INP\", \"r\")) {\n        freopen(\"CATGO.INP\", \"r\", stdin);\n        freopen(\"CATGO.OUT\", \"w\", stdout);\n    }\n    int n;\n    long long M;\n    cin >> n >> M;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    // thử H giảm dần từ max(a) tới khi đủ gỗ: quá chậm khi chiều cao tới 10^9\n    return 0;\n}",file:"CATGO",perf:{gen:n=>n+" "+(n*50)+"\n"+Array.from({length:n},(_,i)=>100+(i*7919)%1000000).join(" "),ns:[200,800,3200],need:"nlogn",limit:n=>Math.round(60*n*Math.log2(n))+3000,why:"Thử từng độ cao là O(n · max a). Tìm kiếm nhị phân trên H chỉ cần khoảng 30 lần kiểm tra, mỗi lần O(n)."}},{t:"Máy sản xuất",d:"File MAYSX.INP: dòng 1 là n, P (1 ≤ n ≤ 10^5, 1 ≤ P ≤ 10^9); dòng 2 là t₁..tₙ (1 ≤ tᵢ ≤ 10^9): máy i làm xong một sản phẩm sau mỗi tᵢ giây. Các máy chạy song song. Ghi vào MAYSX.OUT thời gian ít nhất (giây) để làm được P sản phẩm.",tests:[{in:"3 7\n3 2 5",out:"8"},{in:"1 1000000000\n1000000000",out:"1000000000000000000"},{in:"2 1\n5 7",out:"5"},{in:"3 3\n1 1 1",out:"1"},{in:"2 5\n2 3",out:"6"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"MAYSX.INP\", \"r\")) {\n        freopen(\"MAYSX.INP\", \"r\", stdin);\n        freopen(\"MAYSX.OUT\", \"w\", stdout);\n    }\n    int n;\n    long long P;\n    cin >> n >> P;\n    vector<long long> t(n);\n    for (auto& x : t) cin >> x;\n    // tìm kiếm nhị phân trên thời gian; dừng sớm khi đã đủ P để không tràn số\n    return 0;\n}",file:"MAYSX",perf:{gen:n=>n+" "+(1000000000)+"\n"+Array.from({length:n},(_,i)=>1+(i*7919)%1000).join(" "),ns:[200,800,3200],need:"nlogn",limit:n=>Math.round(120*n*Math.log2(n))+3000,why:"Mô phỏng từng giây là quá chậm khi đáp án tới 10¹⁸. Tìm kiếm nhị phân trên thời gian: khoảng 60 lần kiểm tra, mỗi lần O(n)."}},{t:"Chia dãy",d:"File CHIADAY.INP: dòng 1 là n, k (1 ≤ k ≤ n ≤ 10^5); dòng 2 là n số nguyên dương (≤ 10^9). Chia dãy thành đúng k đoạn liên tiếp khác rỗng. Ghi vào CHIADAY.OUT giá trị nhỏ nhất có thể của tổng lớn nhất trong k đoạn.",tests:[{in:"5 3\n2 4 7 3 5",out:"8"},{in:"1 1\n5",out:"5"},{in:"4 4\n1 2 3 4",out:"4"},{in:"4 1\n1000000000 1000000000 1000000000 1000000000",out:"4000000000"},{in:"6 2\n1 1 1 1 1 10",out:"10"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"CHIADAY.INP\", \"r\")) {\n        freopen(\"CHIADAY.INP\", \"r\", stdin);\n        freopen(\"CHIADAY.OUT\", \"w\", stdout);\n    }\n    int n, k;\n    cin >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    // ok(M): chia tham lam, mỗi đoạn tổng <= M, đếm số đoạn có <= k không\n    return 0;\n}",file:"CHIADAY",perf:{gen:n=>n+" "+Math.max(1,n>>3)+"\n"+Array.from({length:n},(_,i)=>1+(i*7919)%1000000).join(" "),ns:[200,800,3200],need:"nlogn",limit:n=>Math.round(80*n*Math.log2(n))+3000,why:"Thử mọi giá trị M tăng dần là quá chậm. Tìm kiếm nhị phân trên M, mỗi lần kiểm tra tham lam O(n)."}}]);

